        if n!=a {assert(t.nodes[n]==b.nodes[n]);}
        else {match event {
            Step::Promote(_) | Step::Start(_) => {},
            Step::Receive(d) => {assert(sent_ok(b,d.send as int));},
            Step::Save{node,success} => {assert(proposed_ok(b,node as int));},
            Step::Deliver(i) => {},Step::Error(_) => {},
